	}
	engine.plan = blip.Plan{Name: "background", Levels: map[string]blip.Level{level: {Name: level, Freq: "1s"}}}
	engine.collectors[domain] = cl
	engine.collectAt[level] = []*clutch{cl}
	engine.checkAt[level] = nil

